def _is_canonical_request_id(value: object) -> bool:
    # Request ids are uuid4() strings: exactly 36 lowercase hex/hyphen
    # characters. uuid.UUID(..., version=4) additionally confirms the
    # version bits, and the textual checks reject braces, urn prefixes
    # and upper-case spellings that UUID() would otherwise tolerate.
    if not isinstance(value, str) or len(value) != 36:
        return False
    if (
        value[8] != "-"
        or value[13] != "-"
        or value[18] != "-"
        or value[23] != "-"
    ):
        return False
    hex_part = value.replace("-", "")
    if not all(char in _HEX for char in hex_part):
        return False
    try:
        parsed = uuid.UUID(value, version=4)
    except ValueError:
        return False
    return str(parsed) == value

